// Possible processing states returned by the backend.
export type AnalysisStatus =
  | "queued"
  | "analyzing"
  | "completed"
  | "failed"
  | "received";

// Structured diagnosis generated by Ollama.
export interface BugAnalysisResult {
  summary: string;
  severity: "low" | "medium" | "high" | "critical" | "unknown";
  confidence: "low" | "medium" | "high";
  detected_errors: string[];
  screenshot_observations: string[];
  supporting_file_findings: string[];
  likely_root_causes: string[];
  evidence: string[];
  recommended_fixes: string[];
  verification_steps: string[];
  missing_information: string[];
}

// Immediate response returned after submitting a bug report.
export interface AnalyzeSubmissionResponse {
  message: string;
  bug_report_id: number;
  status: AnalysisStatus;
  description: string;
  screenshot_filename: string | null;
  screenshot_size_bytes: number | null;
  supporting_file_filename: string | null;
  supporting_file_size_bytes: number | null;
}

// Complete report returned by GET /bug-reports/{report_id}.
export interface BugReportResponse {
  id: number;
  description: string;
  screenshot_filename: string | null;
  screenshot_size_bytes: number | null;
  supporting_file_filename: string | null;
  supporting_file_size_bytes: number | null;
  status: AnalysisStatus;
  analysis_result: BugAnalysisResult | null;
  created_at: string;
  updated_at: string;
}